def get(rel):
    u = BASE + "/" + rel
    last = None
    for attempt in range(3):
        try:
            req = urllib.request.Request(u, method="HEAD", headers={"User-Agent": "check_site"})
            with urllib.request.urlopen(req, timeout=60) as r:
                n = r.headers.get("Content-Length")
                if n is None:
                    req = urllib.request.Request(u, headers={"User-Agent": "check_site"})
                    with urllib.request.urlopen(req, timeout=180) as r2:
                        n = len(r2.read())
                return rel, r.status, int(n)
        except urllib.error.HTTPError as e:
            return rel, e.code, 0
        except Exception as e:
            last = str(e)[:40]
    return rel, "no answer after 3 tries (" + last + "), run again", 0
skip = {"README.md", "_headers", "vercel.json", "CNAME", ".nojekyll"}
todo = [k for k in MAN if k not in skip]
bad = 0
print("Checking", len(todo), "files, please wait...")
with ThreadPoolExecutor(8) as ex:
    for rel, st, n in ex.map(get, todo):
        if st != 200:
            print("MISSING", st, rel); bad += 1
        elif n != MAN[rel][0]:
            print("WRONG SIZE", rel, n, "expected", MAN[rel][0]); bad += 1
for pg in ("", "upright/", "clearcut/", "verbatim/", "stillreel/", "tailorly/", "enhance/"):
    r = get(pg)
    if r[1] != 200:
        print("PAGE FAILED", pg, r[1]); bad += 1
print("checked", len(todo), "files at", BASE, "-", ("ALL GOOD" if not bad else str(bad) + " problem(s)"))
sys.exit(1 if bad else 0)
